export function getUniqueModels(): string[] {
  return [...new Set(scenarios.map(s => s.model))];
}

export function getUniqueScenarios(): string[] {
  return [...new Set(scenarios.map(s => s.scenario))];
}

export function getScenariosByModel(model: string): ScenarioDataPoint[] {
  return scenarios.filter(s => s.model === model);
}
